-- Historique des états financiers 2020-2025, lot 4 : 40 périodes dont l'unité
-- n'avait pu être établie automatiquement. Unité fixée par l'ordre de grandeur
-- des comptes de la même société déjà en base (ou l'unité déclarée dans le
-- document quand elle est la seule compatible) ; valeurs toujours contrôlées
-- par la variation publiée N - (N-1). Relecture manuelle le 2026-09-24 :
-- écartés CFAC et SITAB 9M 2025 (chiffres du seul 3e trimestre), CIE 2020
-- (ligne illisible), Vivo T1 2025 (chiffre annuel), SAFC 2023 (source ambiguë). Statut 'draft'.
insert into public.financials (ticker,annee,periode,chiffre_affaires,rbe,resultat_exploitation,resultat_activites_ordinaires,resultat_net,total_actif,source,source_url,date_publication,date_arrete,devise,unite,validation_status,statut_audit,validation_notes)
select v.ticker,v.annee::int,v.periode,v.ca::numeric,v.rbe::numeric,v.re::numeric,v.rao::numeric,v.rn::numeric,v.ta::numeric,v.source,
  replace(v.source_url,'~','https://www.brvm.org/sites/default/files/'),v.dp::date,v.da::date,'XOF','FCFA','draft',
  case when v.periode='annuel' then null else 'non_audite' end,
  v.note || ' (source_url), variation N/N-1 publiée contrôlée, relu le 2026-09-24 ; à valider.'
